SELECT COUNT(*) FROM votes as v, comments as c, posts as p, postLinks as pl, postHistory as ph WHERE p.Id = v.PostId AND p.Id = pl.RelatedPostId AND p.Id = c.PostId AND p.Id = ph.PostId AND v.CreationDate<='2014-09-10 00:00:00'::timestamp AND c.Score=0 AND p.Score<=32 AND p.ViewCount<=4146 AND pl.LinkTypeId=1;